<script setup>
import { ref, computed, onMounted } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { get, post, config } from '@/utils/api.js' // <-- 导入 post 方法

// 从缓存读取预约表单数据
const appointmentFormData = ref({})
const appointmentNo = ref('')

onLoad((options) => {
  // 处理 appointmentNo
  if (options && options.appointmentNo) {
    appointmentNo.value = options.appointmentNo;
  }

  // 读取缓存数据
  try {
    const cachedData = uni.getStorageSync('appointmentFormData')
    if (cachedData) {
      appointmentFormData.value = cachedData;
      // 如果 URL 中没有 appointmentNo，尝试从缓存中获取
      if (!appointmentNo.value && cachedData.appointmentNo) {
        appointmentNo.value = cachedData.appointmentNo;
      }
    }
  } catch (e) {
    console.error('读取预约表单缓存失败:', e);
  }

  // 如果 appointmentNo 存在，则开始加载数据
  if (appointmentNo.value) {
    fetchAttendants();
  } else {
    console.error('缺少 appointmentNo，无法加载数据');
  }
})

// --- API 请求函数 ---
const loading = ref(true)
const rawCompanions = ref([])

const fetchAttendants = () => {
  if (!appointmentNo.value) {
    console.error('缺少 appointmentNo，无法请求 API');
    loading.value = false;
    return;
  }

  // --- 修改了 API 路径 ---
  get(`/ai/guide/attendants/match?appointmentNo=${encodeURIComponent(appointmentNo.value)}`)
    .then(res => {
      if (res.data && Array.isArray(res.data.attendants)) {
        // 处理每个伴诊师的 photo 字段，确保是完整 URL
        rawCompanions.value = res.data.attendants.map(attendant => {
          // 构造完整的图片 URL
          let photoUrl = attendant.photo;
          // 检查 photoUrl 是否存在且不是完整的 URL (不以 http 开头)
          if (photoUrl && !photoUrl.startsWith('http')) {
            // 如果是相对路径，则拼接 config.baseURL
            if (photoUrl.startsWith('/')) {
               // 去掉开头的 /
               photoUrl = photoUrl.substring(1);
            }
            // --- 修复关键点 ---
            const normalizedBaseUrl = config.baseURL.endsWith('/') ? config.baseURL : config.baseURL + '/';
            photoUrl = normalizedBaseUrl + photoUrl;
          }
          // 可选：打印日志确认 URL
          console.log(`Constructed photo URL for ${attendant.name}:`, photoUrl);

          return {
            id: attendant.id,
            name: attendant.name,
            photo: photoUrl, // 确保是完整 URL
            score: attendant.score,
            professionalField: attendant.professionalField,
            experienceYears: attendant.experienceYears, // 保留经验年限
            reviewCount: attendant.reviewCount,
            introduction: attendant.introduction,
            qualifications: attendant.qualifications,
            services: attendant.services,
            recommended: attendant.recommended,
            phone: attendant.phone // --- 添加电话字段 ---
          };
        });
      } else {
        console.error('API 返回数据格式错误:', res.data);
      }
    })
    .catch(err => {
      console.error('API 请求失败:', err);
    })
    .finally(() => {
      loading.value = false;
    });
};

// 时间比较工具函数
const timeToMinutes = (timeStr) => {
  if (!timeStr) return -1
  const [h, m] = timeStr.split(':').map(Number)
  return h * 60 + m
}

// 排序相关
const sortKey = ref('ai')

// --- 控制显示数量 ---
const displayedCount = ref(3); // 初始只显示 3 个

// --- 使用 computed 来控制显示的陪诊师列表 ---
const displayedCompanions = computed(() => {
  return companions.value.slice(0, displayedCount.value);
});

// 计算排序后的列表
const companions = computed(() => {
  let list = [...rawCompanions.value]
  if (sortKey.value === 'ai') {
    list.sort((a, b) => (b.recommended - a.recommended))
  } else if (sortKey.value === 'rating') {
    list.sort((a, b) => b.score - a.score)
  } else if (sortKey.value === 'experience') {
    list.sort((a, b) => b.experienceYears - a.experienceYears) // 按经验年限降序
  }
  return list
})

// 设置排序类型
const setSort = (key) => {
  sortKey.value = key
}

// 详情弹窗相关
const showDetail = ref(false)
const currentCompanion = ref({})

// 查看详情
const viewDetail = (item) => {
  currentCompanion.value = item
  showDetail.value = true
}

// 关闭详情
const closeDetail = () => {
  showDetail.value = false
}

// --- 加载全部陪诊师 ---
const loadAllCompanions = () => {
  displayedCount.value = companions.value.length;
};

// --- 发送选择请求 ---
const sendSelectionRequest = async (companion) => {
  console.log('用户选择的陪诊师对象:', companion);

  // --- 构建订单请求体 ---
  const orderRequestBody = {
    appointmentNo: appointmentNo.value, // --- 使用从 URL 或缓存获取的 appointmentNo ---
    attendantId: companion.id // --- 使用选中的陪诊师 ID ---
  };

  try {
    // --- 调用 POST 接口创建订单 ---
    const orderResponse = await post('/ai/guide/orders', orderRequestBody);

    // --- 检查响应 ---
    if (orderResponse && orderResponse.data && orderResponse.data.orderNo) {
      const orderNo = orderResponse.data.orderNo;
      console.log('成功创建订单，订单号:', orderNo);

      // --- 跳转到订单确认页面 (传递 orderNo) ---
      uni.navigateTo({
        url: `/pages/AItriage/04_OrderConfirmPage?orderNo=${encodeURIComponent(orderNo)}`
      });

    } else {
      console.error('API 创建订单返回数据格式错误:', orderResponse);
      uni.showToast({ title: '创建订单失败', icon: 'none' });
    }
  } catch (error) {
    console.error('创建订单请求失败:', error);
    uni.showToast({ title: '创建订单失败', icon: 'none' });
  }
};

// 从列表选择陪诊师
const selectCompanion = (item) => {
  sendSelectionRequest(item)
}

// 从详情页选择陪诊师
const selectFromDetail = () => {
  closeDetail()
  sendSelectionRequest(currentCompanion.value)
}

</script>

